import { relative } from 'node:path';
import {
  colon,
  colorizeKey,
  colorizeNumber,
  getAppLogger,
} from '@intlayer/config/logger';
import {
  type GetConfigurationOptions,
  getConfiguration,
} from '@intlayer/config/node';
import { prepareIntlayer } from '@intlayer/engine/cli';
import { formatPath } from '@intlayer/engine/utils';
import { getUnmergedDictionaries } from '@intlayer/unmerged-dictionaries-entry';

type ListContentDeclarationOptions = {
  configOptions?: GetConfigurationOptions;
  json?: boolean;
  absolute?: boolean;
};

export const listContentDeclarationRows = async (
  options?: ListContentDeclarationOptions
) => {
  const config = getConfiguration(options?.configOptions);

  await prepareIntlayer(config);

  const unmergedDictionariesRecord = getUnmergedDictionaries(config);

  const rows = Object.values(unmergedDictionariesRecord)
    .flat()
    .map((dictionary) => ({
      key: dictionary.key ?? '',
      path: options?.absolute
        ? (dictionary.filePath ?? 'Remote')
        : relative(config.system.baseDir, dictionary.filePath ?? 'Remote'),
    }));
  return rows;
};

export const listContentDeclaration = async (
  options?: ListContentDeclarationOptions
) => {
  const rows = await listContentDeclarationRows(options);

  if (options?.json) {
    console.log(JSON.stringify(rows));
    return;
  }

  const config = getConfiguration(options?.configOptions);
  const appLogger = getAppLogger(config);

  const lines = rows.map((row) =>
    [
      colon(` - ${colorizeKey(row.key)}`, {
        colSize: rows.map((row) => row.key.length),
        maxSize: 60,
      }),
      ' - ',
      formatPath(row.path),
    ].join('')
  );

  appLogger(`Content declaration files:`);

  lines.forEach((line) => {
    appLogger(line, {
      level: 'info',
    });
  });

  appLogger(`Total content declaration files: ${colorizeNumber(rows.length)}`);
};
